const r = await tools.exec_command({"cmd":"task_tmp=$(find /private/tmp -maxdepth 1 -type d -name 'gkeyll-perlmutter-ci.*' | tail -n 1)\nfor source_file in \"$task_tmp\"/*; do\n  case \"$source_file\" in *.patch) continue;; esac\n  printf '\\036%s\\n' \"$(basename \"$source_file\")\"\n  cat \"$source_file\"\ndone","workdir":"/Users/mfrancis/Documents/gkeyll/code/gkeyll_v0/gkeyll","yield_time_ms":10000,"max_output_tokens":200000});
const chunks = r.output.split("\x1e").filter(Boolean);
let patch = "*** Begin Patch\n";
for (const chunk of chunks) {
  const nl = chunk.indexOf("\n");
  const name = chunk.slice(0, nl);
  const body = chunk.slice(nl + 1);
  patch += `*** Add File: ci/jenkins/${name}\n` + body.split("\n").map(line => "+" + line).join("\n") + "\n";
}
patch += "*** End Patch";
const applied = await tools.apply_patch(patch);
text(JSON.stringify(applied));
